<?php
/** Plugin Name: TEMP PS S1721o deploy: petshop-dydziai-automatas v1.0 + Ryto sargo lempute "seimos". 1 lint+dry testai (tmp include), 2 rasyti+patch+heartbeat, 3 po deploy, 9 atstatyti */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1721o'])) return; $f=$_GET['ps_s1721o']; $r=['v'=>'S1721o','faze'=>$f]; @set_time_limit(170); global $wpdb; $P=$wpdb->prefix;
  $mu=WPMU_PLUGIN_DIR; $fn='petshop-dydziai-automatas.php'; $ry="$mu/petshop-rytas.php"; $arch=dirname(ABSPATH).'/ps-archyvas'; $bak="$arch/petshop-rytas.php.bak_s1721"; $tmp="$arch/tmp_s1721o_automatas.php";
  $b64=''; $md5='0121ca60a19c925475ef3754f63e6389'; $patch=base64_decode(''); $marker="\t\t/* neišsiųsti */\n\t\t\$n = self::neissiusti_sk();";
  $ua=['timeout'=>25,'sslverify'=>false,'user-agent'=>'Mozilla/5.0 ps-s1721','cookies'=>['ps_js'=>'1']];
  $dry=function() use (&$r,$wpdb,$P){
    $t0=microtime(true); $A='Petshop_Dydziu_Automatas';
    foreach([18584,18590,36002,18587,36003] as $id){ $r['pilot'][$id]=['pav'=>get_the_title($id),'baze'=>implode(' ',$A::baze(get_the_title($id))),'rasti'=>$A::rasti($id,true,true),'kat'=>wp_get_object_terms($id,'product_cat',['fields'=>'slugs'])]; }
    foreach([18560,18582] as $id){ $r['kiti'][$id]=['pav'=>get_the_title($id),'rasti'=>$A::rasti($id,true)]; }
    // visos publikuotos prekes be seimos KAT kategorijose: tipu pasiskirstymas (dry)
    $ids=$wpdb->get_col("SELECT p.ID FROM {$wpdb->posts} p WHERE p.post_type='product' AND p.post_status='publish' AND NOT EXISTS (SELECT 1 FROM {$wpdb->postmeta} m WHERE m.post_id=p.ID AND m.meta_key='_ps_dydzio_seima' AND m.meta_value<>'') ORDER BY p.ID DESC LIMIT 400");
    $tip=[]; $pvz=[]; foreach($ids as $id){ $x=$A::rasti((int)$id,true); $tip[$x['tipas']]=($tip[$x['tipas']]??0)+1; if(in_array($x['tipas'],['tiksli','kandidatas','dp']) && count($pvz)<15) $pvz[]=[$id,get_the_title($id),$x]; }
    $r['dry_400']=['tipai'=>$tip,'pvz'=>$pvz,'sek'=>round(microtime(true)-$t0,2)];
    $r['suvestine']=$A::suvestine(26);
    $r['dydis_pvz']=array_map([$A,'dydis_is_pavadinimo'],['Exclusion Hypoallergenic 2 x 7 kg','Josera 12,5 kg','Monge 2+1 kg','Animonda 400g','Miamor 100 g','Ontario 6 x 400 g']);
  };
  try{
  if($f==='1'){
    $code=base64_decode($b64); $r['md5_ok']=md5($code)===$md5; try{ token_get_all($code,TOKEN_PARSE); $r['lint']='ok'; }catch(Throwable $e){ $r['lint']='KLAIDA '.$e->getMessage(); }
    $r['rytas_md5']=is_file($ry)?md5_file($ry):'NERA'; $src=is_file($ry)?file_get_contents($ry):''; $r['marker_n']=substr_count($src,$marker); $r['jau_patchinta']=strpos($src,'Petshop_Dydziu_Automatas')!==false;
    $r['rytas_versija']=preg_match('/Version:\s*([\d.]+)/',$src,$m)?$m[1]:'?'; $r['arch_rasoma']=is_dir($arch)&&is_writable($arch); $r['mu_rasoma']=is_writable($mu);
    // kategoriju slugai su prekiu skaiciais (KAT patikrai)
    $r['kategorijos']=$wpdb->get_results("SELECT t.slug, tt.count, tt.parent FROM {$wpdb->term_taxonomy} tt JOIN {$wpdb->terms} t ON t.term_id=tt.term_id WHERE tt.taxonomy='product_cat' AND tt.count>0 ORDER BY tt.count DESC LIMIT 80",ARRAY_A);
    if($r['lint']==='ok'&&$r['md5_ok']&&!class_exists('Petshop_Dydziu_Automatas')){ file_put_contents($tmp,$code); include $tmp; @unlink($tmp); $r['tmp_include']='ok'; $dry(); }
  }
  if($f==='2'){
    $code=base64_decode($b64); if(md5($code)!==$md5) throw new Exception('md5'); token_get_all($code,TOKEN_PARSE);
    $src=file_get_contents($ry); if(substr_count($src,$marker)!==1) throw new Exception('marker '.substr_count($src,$marker)); if(strpos($src,'Petshop_Dydziu_Automatas')!==false) throw new Exception('jau patchinta');
    if(!is_file($bak)){ copy($ry,$bak); } $r['bak']=md5_file($bak);
    $new=str_replace($marker,$patch.$marker,$src); $new=preg_replace('/(Version:\s*)1\.4\b/','${1}1.5',$new,1); token_get_all($new,TOKEN_PARSE);
    file_put_contents("$mu/$fn",$code); $r['automatas_md5']=md5_file("$mu/$fn");
    file_put_contents($ry,$new); $r['rytas_md5']=md5_file($ry); $r['rytas_kb']=round(filesize($ry)/1024,1);
    delete_transient('ps_dydz_auto_bazes');
    $hb=wp_remote_get(home_url('/?ps_hb='.time()),$ua); $c=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $r['heartbeat']=$c;
    if($c>=500||$c===0){ copy($bak,$ry); @unlink("$mu/$fn"); $r['ATSTATYTA']='heartbeat '.$c; }
  }
  if($f==='3'){
    $r['klase']=class_exists('Petshop_Dydziu_Automatas'); $r['rytas_patch']=strpos(file_get_contents($ry),'Petshop_Dydziu_Automatas')!==false; $r['rytas_md5']=md5_file($ry);
    if($r['klase']) $dry();
    // Ryto sargo patikros — surandam klase su neissiusti_sk
    foreach(get_declared_classes() as $c){ if(method_exists($c,'neissiusti_sk')&&method_exists($c,'patikros')){ $r['rytas_klase']=$c; try{ $m=new ReflectionMethod($c,'patikros'); $m->setAccessible(true); $out=$m->invoke(null); $r['patikros_tipas']=gettype($out); if(is_array($out)){ foreach($out as $k=>$v){ if((is_string($k)&&$k==='seimos')||(is_array($v)&&(($v['key']??$v['id']??'')==='seimos'))) $r['patikros_seimos']=$v; } $r['patikros_n']=count($out); $r['patikros_keys']=array_slice(array_keys($out),0,40); } }catch(Throwable $e){ $r['patikros_err']=$e->getMessage(); } break; } }
    $lf=ini_get('error_log'); if($lf&&is_file($lf)){ $sz=filesize($lf); $h2=fopen($lf,'r'); fseek($h2,max(0,$sz-3000)); $r['log_uodega']=array_slice(array_filter(explode("\n",stream_get_contents($h2))),-3); fclose($h2); }
  }
  if($f==='9'){ if(is_file($bak)){ copy($bak,$ry); $r['rytas_atstatytas']=md5_file($ry); } @unlink("$mu/$fn"); $r['automatas_pasalintas']=!file_exists("$mu/$fn"); delete_transient('ps_dydz_auto_bazes'); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
}, 1);
